args.command:
perl -MFile::Find -e '
my (@files,@decls,%calls);
find(sub{return unless -f && /\.go$/; push @files,$File::Find::name}, ".");
for my $f (@files){open my $h,"<",$f or die $!; local $/; my $s=<$h>; next if $s =~ m{^// Code generated .* DO NOT EDIT\.}m; my $clean=$s; $clean =~ s{//[^\n]*}{}g; $clean =~ s{/\*.*?\*/}{}gs; $clean =~ s{"(?:\\.|[^"\\])*"}{""}gs; while($clean =~ /\b([A-Za-z_]\w*)\s*\(/g){$calls{$1}++} next unless $f =~ m{(?:^|/)internal/}; my $pkg=$clean =~ /^\s*package\s+(\w+)/m ? $1:"?"; while($clean =~ /^\s*func\s+(?:\(\s*([^)]*?)\s*\)\s*)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\]\s*)?\(/mg){my($recv,$name)=($1,$2); my $before=substr($clean,0,$-[0]); my $line=1+($before=~tr/\n//); push @decls,[$calls{$name}||0,$name,$pkg,$f,$line,defined($recv)?$recv:""]}}
@decls=sort{$b->[0]<=>$a->[0]||$a->[1]cmp$b->[1]}@decls;
print "files ".scalar(@files)." decls ".scalar(@decls)."\n";
for my $d (@decls[0..39]){print join("\t",@$d),"\n"}
'

