print "all=$all generated=$generated analyzed=$nongenerated test_files=$tests\n"; for my $n(@names){print "$n sites=$c{$n} files=".scalar(keys %{$files{$n}})." prod=$prod{$n} test=$test{$n}\n"; for my $f(sort keys %{$files{$n}}){print "  $files{$n}{$f}\t$f\n"}}
